  'Eligible members will be notified. The sealed fairness code is fixed now, and prizes, dates and rules can\'t change after publishing.': 'ਯੋਗ ਮੈਂਬਰਾਂ ਨੂੰ ਸੂਚਨਾ ਜਾਵੇਗੀ। ਸੀਲਬੰਦ ਨਿਰਪੱਖਤਾ ਕੋਡ ਹੁਣ ਤੈਅ ਹੋ ਜਾਵੇਗਾ, ਅਤੇ ਜਾਰੀ ਹੋਣ ਤੋਂ ਬਾਅਦ ਇਨਾਮ, ਤਾਰੀਖਾਂ ਅਤੇ ਨਿਯਮ ਨਹੀਂ ਬਦਲ ਸਕਦੇ।',
  'Close entries now?': 'ਐਂਟਰੀਆਂ ਹੁਣੇ ਬੰਦ ਕਰੀਏ?',
  'Entries are due to close {date}. Closing early stops anyone else from joining. This can\'t be undone.': 'ਐਂਟਰੀਆਂ {date} ਨੂੰ ਬੰਦ ਹੋਣੀਆਂ ਹਨ। ਪਹਿਲਾਂ ਬੰਦ ਕਰਨ \'ਤੇ ਕੋਈ ਹੋਰ ਸ਼ਾਮਲ ਨਹੀਂ ਹੋ ਸਕੇਗਾ। ਇਹ ਵਾਪਸ ਨਹੀਂ ਹੋ ਸਕਦਾ।',
  'Close entries': 'ਐਂਟਰੀਆਂ ਬੰਦ ਕਰੋ',
  'Run the draw now?': 'ਡਰਾਅ ਹੁਣੇ ਕੱਢੀਏ?',
  '{entrants} entrant(s) for {prizes} prize(s). Winners are picked by the fair method below and notified straight away. This can\'t be undone.': '{prizes} ਇਨਾਮਾਂ ਲਈ {entrants} ਭਾਗੀਦਾਰ। ਜੇਤੂ ਹੇਠਾਂ ਦਿੱਤੇ ਨਿਰਪੱਖ ਤਰੀਕੇ ਨਾਲ ਚੁਣੇ ਜਾਣਗੇ ਅਤੇ ਤੁਰੰਤ ਸੂਚਿਤ ਹੋਣਗੇ। ਇਹ ਵਾਪਸ ਨਹੀਂ ਹੋ ਸਕਦਾ।',
  'Run draw': 'ਡਰਾਅ ਕੱਢੋ',
