  'Everyone who entered will be told. This cannot be undone.': 'ਸਾਰੇ ਭਾਗੀਦਾਰਾਂ ਨੂੰ ਦੱਸਿਆ ਜਾਵੇਗਾ। ਇਹ ਵਾਪਸ ਨਹੀਂ ਹੋ ਸਕਦਾ।',
