  'Promote reserve': 'ਰਿਜ਼ਰਵ ਨੂੰ ਜੇਤੂ ਬਣਾਓ',
  'Reserves (in order)': 'ਰਿਜ਼ਰਵ (ਕ੍ਰਮ ਅਨੁਸਾਰ)',
  'promoted': 'ਜੇਤੂ ਬਣਾਇਆ',
  'Promote next reserve for {prize}?': '{prize} ਲਈ ਅਗਲੇ ਰਿਜ਼ਰਵ ਨੂੰ ਜੇਤੂ ਬਣਾਈਏ?',
  '{name} will lose this prize and the next person on the reserve list will be told they won.': '{name} ਤੋਂ ਇਹ ਇਨਾਮ ਹਟ ਜਾਵੇਗਾ ਅਤੇ ਰਿਜ਼ਰਵ ਸੂਚੀ ਦੇ ਅਗਲੇ ਵਿਅਕਤੀ ਨੂੰ ਦੱਸਿਆ ਜਾਵੇਗਾ ਕਿ ਉਹ ਜਿੱਤੇ।',
  'Why can\'t the winner receive it?': 'ਜੇਤੂ ਇਸ ਨੂੰ ਕਿਉਂ ਨਹੀਂ ਲੈ ਸਕਦੇ?',
  'Flat': 'ਫਲੈਟ',
  'Entry id': 'ਐਂਟਰੀ ID',
  'Entrants': 'ਭਾਗੀਦਾਰ',
  '{n} active': '{n} ਸਰਗਰਮ',
  'Search entrants': 'ਭਾਗੀਦਾਰ ਖੋਜੋ',
  'Search name or flat': 'ਨਾਮ ਜਾਂ ਫਲੈਟ ਖੋਜੋ',
  'No entrants yet': 'ਹਾਲੇ ਕੋਈ ਭਾਗੀਦਾਰ ਨਹੀਂ',
  'Members who join appear here.': 'ਸ਼ਾਮਲ ਹੋਣ ਵਾਲੇ ਮੈਂਬਰ ਇੱਥੇ ਦਿਖਣਗੇ।',
  'How we keep it fair': 'ਅਸੀਂ ਇਸ ਨੂੰ ਨਿਰਪੱਖ ਕਿਵੇਂ ਰੱਖਦੇ ਹਾਂ',
  'When the draw opened, the computer picked a secret random code and showed you only its fingerprint (the sealed code). The secret can\'t be changed later without the fingerprint changing.': 'ਡਰਾਅ ਖੁੱਲ੍ਹਣ ਵੇਲੇ ਕੰਪਿਊਟਰ ਨੇ ਇੱਕ ਗੁਪਤ ਰੈਂਡਮ ਕੋਡ ਚੁਣਿਆ ਅਤੇ ਤੁਹਾਨੂੰ ਸਿਰਫ਼ ਉਸ ਦਾ ਫਿੰਗਰਪ੍ਰਿੰਟ (ਸੀਲਬੰਦ ਕੋਡ) ਦਿਖਾਇਆ। ਫਿੰਗਰਪ੍ਰਿੰਟ ਬਦਲੇ ਬਿਨਾਂ ਗੁਪਤ ਕੋਡ ਬਾਅਦ ਵਿੱਚ ਨਹੀਂ ਬਦਲਿਆ ਜਾ ਸਕਦਾ।',
  'When entries closed, we published a fingerprint of the full entry list, so nobody can be added or removed afterwards.': 'ਐਂਟਰੀਆਂ ਬੰਦ ਹੋਣ \'ਤੇ ਅਸੀਂ ਪੂਰੀ ਐਂਟਰੀ ਸੂਚੀ ਦਾ ਫਿੰਗਰਪ੍ਰਿੰਟ ਜਾਰੀ ਕੀਤਾ, ਤਾਂ ਜੋ ਬਾਅਦ ਵਿੱਚ ਕਿਸੇ ਨੂੰ ਜੋੜਿਆ ਜਾਂ ਹਟਾਇਆ ਨਾ ਜਾ ਸਕੇ।',
  'Each entry gets a score made from the secret code and the entry\'s id (HMAC-SHA256). Lowest score is drawn first. Prizes go in the listed order, one per person (one per flat); the next people become reserves.': 'ਹਰ ਐਂਟਰੀ ਨੂੰ ਗੁਪਤ ਕੋਡ ਅਤੇ ਐਂਟਰੀ ID ਤੋਂ ਬਣਿਆ ਸਕੋਰ ਮਿਲਦਾ ਹੈ (HMAC-SHA256)। ਸਭ ਤੋਂ ਘੱਟ ਸਕੋਰ ਪਹਿਲਾਂ ਨਿਕਲਦਾ ਹੈ। ਇਨਾਮ ਦਿੱਤੇ ਕ੍ਰਮ ਵਿੱਚ, ਹਰ ਵਿਅਕਤੀ ਨੂੰ ਇੱਕ (ਹਰ ਫਲੈਟ ਨੂੰ ਇੱਕ) ਮਿਲਦੇ ਹਨ; ਅਗਲੇ ਲੋਕ ਰਿਜ਼ਰਵ ਬਣਦੇ ਹਨ।',
  'Each entry gets a score made from the secret code and the entry\'s id (HMAC-SHA256). Lowest score is drawn first. Prizes go in the listed order, one per person; the next people become reserves.': 'ਹਰ ਐਂਟਰੀ ਨੂੰ ਗੁਪਤ ਕੋਡ ਅਤੇ ਐਂਟਰੀ ID ਤੋਂ ਬਣਿਆ ਸਕੋਰ ਮਿਲਦਾ ਹੈ (HMAC-SHA256)। ਸਭ ਤੋਂ ਘੱਟ ਸਕੋਰ ਪਹਿਲਾਂ ਨਿਕਲਦਾ ਹੈ। ਇਨਾਮ ਦਿੱਤੇ ਕ੍ਰਮ ਵਿੱਚ, ਹਰ ਵਿਅਕਤੀ ਨੂੰ ਇੱਕ ਮਿਲਦਾ ਹੈ; ਅਗਲੇ ਲੋਕ ਰਿਜ਼ਰਵ ਬਣਦੇ ਹਨ।',
  'After the draw the secret code is revealed. Anyone can check it matches the sealed code and recompute every score.': 'ਡਰਾਅ ਤੋਂ ਬਾਅਦ ਗੁਪਤ ਕੋਡ ਦੱਸ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ। ਕੋਈ ਵੀ ਜਾਂਚ ਸਕਦਾ ਹੈ ਕਿ ਇਹ ਸੀਲਬੰਦ ਕੋਡ ਨਾਲ ਮਿਲਦਾ ਹੈ ਅਤੇ ਹਰ ਸਕੋਰ ਦੁਬਾਰਾ ਕੱਢ ਸਕਦਾ ਹੈ।',
