  'Revealed secret code': 'ਦੱਸਿਆ ਗਿਆ ਗੁਪਤ ਕੋਡ',
  'Your entry id:': 'ਤੁਹਾਡੀ ਐਂਟਰੀ ID:',
  'Verify this draw': 'ਇਸ ਡਰਾਅ ਦੀ ਜਾਂਚ ਕਰੋ',
  'Check in my browser': 'ਮੇਰੇ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਜਾਂਚੋ',
  'Secret and entry list match the sealed codes': 'ਗੁਪਤ ਕੋਡ ਅਤੇ ਐਂਟਰੀ ਸੂਚੀ ਸੀਲਬੰਦ ਕੋਡਾਂ ਨਾਲ ਮਿਲਦੇ ਹਨ',
  'Mismatch — contact the committee': 'ਮੇਲ ਨਹੀਂ ਖਾਂਦਾ — ਕਮੇਟੀ ਨਾਲ ਸੰਪਰਕ ਕਰੋ',
  'To recompute a score yourself: HMAC-SHA256 with key = revealed secret code and message = entry id. Sort ascending.': 'ਸਕੋਰ ਖ਼ੁਦ ਕੱਢਣ ਲਈ: HMAC-SHA256, key = ਦੱਸਿਆ ਗਿਆ ਗੁਪਤ ਕੋਡ ਅਤੇ message = ਐਂਟਰੀ ID। ਛੋਟੇ ਤੋਂ ਵੱਡੇ ਕ੍ਰਮ ਵਿੱਚ ਲਗਾਓ।',
